func twoSumSorted(nums []int, target int) (int, int) {
	i, j := 0, len(nums)-1
	for i < j {
		sum := nums[i] + nums[j]
		switch {
		case sum == target:
			return i, j
		case sum < target:
			i++
		default:
			j--
		}
	}
	return -1, -1
}

func lengthOfLongestSubstring(s string) int {
	last := make(map[byte]int)
	best, left := 0, 0
	for right := 0; right < len(s); right++ {
		c := s[right]
		if idx, ok := last[c]; ok && idx >= left {
			left = idx + 1
		}
		last[c] = right
		if w := right - left + 1; w > best {
			best = w
		}
	}
	return best
}

type Fenwick struct{ t []int }

func NewFenwick(n int) *Fenwick { return &Fenwick{t: make([]int, n+1)} }

func (f *Fenwick) Add(i, delta int) { // 1-indexed
	for ; i < len(f.t); i += i & -i {
		f.t[i] += delta
	}
}

func (f *Fenwick) PrefixSum(i int) int {
	s := 0
	for ; i > 0; i -= i & -i {
		s += f.t[i]
	}
	return s
}

func (f *Fenwick) RangeSum(l, r int) int { return f.PrefixSum(r) - f.PrefixSum(l-1) }

func minSubArrayLen(target int, nums []int) int {
	best := len(nums) + 1
	sum, left := 0, 0
	for right, v := range nums {
		sum += v
		for sum >= target {
			if w := right - left + 1; w < best {
				best = w
			}
			sum -= nums[left]
			left++
		}
	}
	if best == len(nums)+1 {
		return 0
	}
	return best
}

func twoSum(nums []int, target int) (int, int) {
	seen := make(map[int]int, len(nums))
	for i, v := range nums {
		if j, ok := seen[target-v]; ok {
			return j, i
		}
		seen[v] = i
	}
	return -1, -1
}

