func (s *MinStack) Push(x int) {
	s.data = append(s.data, x)
	if len(s.mins) == 0 || x <= s.mins[len(s.mins)-1] {
		s.mins = append(s.mins, x)
	} else {
		s.mins = append(s.mins, s.mins[len(s.mins)-1])
	}
}

