}

func (q *Queue) Enqueue(x int) { q.in = append(q.in, x) }

func (q *Queue) transfer() {
	if len(q.out) == 0 {
		for len(q.in) > 0 {
			q.out = append(q.out, q.in[len(q.in)-1])
			q.in = q.in[:len(q.in)-1]
		}
	}
}

func (q *Queue) Dequeue() (int, bool) {
	q.transfer()
	if len(q.out) == 0 {
		return 0, false
	}
	x := q.out[len(q.out)-1]
	q.out = q.out[:len(q.out)-1]
	return x, true
}

type ListNode struct {
