func levelOrder(root *TreeNode) [][]int {
	if root == nil {
		return nil
	}
	var res [][]int
	queue := []*TreeNode{root}
	for len(queue) > 0 {
		n := len(queue)
		level := make([]int, 0, n)
		for i := 0; i < n; i++ {
			node := queue[0]
			queue = queue[1:]
			level = append(level, node.Val)
			if node.Left != nil {
				queue = append(queue, node.Left)
			}
			if node.Right != nil {
				queue = append(queue, node.Right)
			}
		}
		res = append(res, level)
	}
	return res
}

func isValidBST(root *TreeNode) bool {
	var check func(n *TreeNode, low, high *int) bool
	check = func(n *TreeNode, low, high *int) bool {
		if n == nil {
			return true
		}
		if low != nil && n.Val <= *low {
			return false
		}
		if high != nil && n.Val >= *high {
			return false
		}
		return check(n.Left, low, &n.Val) && check(n.Right, &n.Val, high)
	}
	return check(root, nil, nil)
}

func lowestCommonAncestorBST(root, p, q *TreeNode) *TreeNode {
	for root != nil {
		switch {
		case p.Val < root.Val && q.Val < root.Val:
			root = root.Left
		case p.Val > root.Val && q.Val > root.Val:
			root = root.Right
		default:
			return root
		}
	}
	return nil
}

import (
