	"strings"
)

func serialize(root *TreeNode) string {
	var sb strings.Builder
	var dfs func(n *TreeNode)
	dfs = func(n *TreeNode) {
		if n == nil {
			sb.WriteString("#,")
			return
		}
		sb.WriteString(strconv.Itoa(n.Val))
		sb.WriteByte(',')
		dfs(n.Left)
		dfs(n.Right)
	}
	dfs(root)
	return sb.String()
}

func deserialize(data string) *TreeNode {
	tokens := strings.Split(strings.TrimSuffix(data, ","), ",")
	i := 0
	var build func() *TreeNode
	build = func() *TreeNode {
		tok := tokens[i]
		i++
		if tok == "#" {
			return nil
		}
		v, _ := strconv.Atoi(tok)
		n := &TreeNode{Val: v}
		n.Left = build()
		n.Right = build()
		return n
	}
	return build()
}

type Trie struct {
