func dijkstra(adj [][]edge, src int) []int {
	const inf = int(1e18)
	dist := make([]int, len(adj))
	for i := range dist {
		dist[i] = inf
	}
	dist[src] = 0
	h := &pq{{src, 0}}
	for h.Len() > 0 {
		cur := heap.Pop(h).(item)
		if cur.dist > dist[cur.node] {
			continue // stale entry
		}
		for _, e := range adj[cur.node] {
			if nd := cur.dist + e.w; nd < dist[e.to] {
				dist[e.to] = nd
				heap.Push(h, item{e.to, nd})
			}
		}
	}
	return dist
}

type DSU struct {
	parent, rank []int
	count        int
}

func NewDSU(n int) *DSU {
	p := make([]int, n)
	for i := range p {
		p[i] = i
	}
	return &DSU{parent: p, rank: make([]int, n), count: n}
}

func (d *DSU) Find(x int) int {
	for d.parent[x] != x {
		d.parent[x] = d.parent[d.parent[x]] // path compression
		x = d.parent[x]
	}
	return x
}

// Union returns false if x and y were already connected (=> cycle).
func (d *DSU) Union(x, y int) bool {
	rx, ry := d.Find(x), d.Find(y)
	if rx == ry {
		return false
	}
	if d.rank[rx] < d.rank[ry] {
		rx, ry = ry, rx
	}
	d.parent[ry] = rx
	if d.rank[rx] == d.rank[ry] {
		d.rank[rx]++
	}
	d.count--
	return true
}

func permute(nums []int) [][]int {
	var res [][]int
	var backtrack func(start int)
	backtrack = func(start int) {
		if start == len(nums) {
			perm := make([]int, len(nums))
			copy(perm, nums)
			res = append(res, perm)
			return
		}
		for i := start; i < len(nums); i++ {
			nums[start], nums[i] = nums[i], nums[start]
			backtrack(start + 1)
			nums[start], nums[i] = nums[i], nums[start]
		}
	}
	backtrack(0)
	return res
}

func combine(n, k int) [][]int {
	var res [][]int
	path := make([]int, 0, k)
	var backtrack func(start int)
	backtrack = func(start int) {
		if len(path) == k {
			c := make([]int, k)
			copy(c, path)
			res = append(res, c)
			return
		}
		// prune: need k-len(path) more, stop when not enough remain
		for i := start; i <= n-(k-len(path))+1; i++ {
			path = append(path, i)
			backtrack(i + 1)
			path = path[:len(path)-1]
		}
	}
	backtrack(1)
	return res
}

func totalNQueens(n int) int {
	count := 0
	cols := make([]bool, n)
	diag1 := make([]bool, 2*n) // row+col
	diag2 := make([]bool, 2*n) // row-col+n
	var place func(row int)
	place = func(row int) {
		if row == n {
			count++
			return
		}
		for col := 0; col < n; col++ {
			d1, d2 := row+col, row-col+n
			if cols[col] || diag1[d1] || diag2[d2] {
				continue
			}
			cols[col], diag1[d1], diag2[d2] = true, true, true
			place(row + 1)
			cols[col], diag1[d1], diag2[d2] = false, false, false
		}
	}
	place(0)
	return count
}

func coinChange(coins []int, amount int) int {
	const inf = 1 << 30
	dp := make([]int, amount+1)
	for i := 1; i <= amount; i++ {
		dp[i] = inf
	}
	for a := 1; a <= amount; a++ {
		for _, c := range coins {
			if c <= a && dp[a-c]+1 < dp[a] {
				dp[a] = dp[a-c] + 1
			}
		}
	}
	if dp[amount] >= inf {
		return -1
	}
	return dp[amount]
}

func knapsack01(weights, values []int, W int) int {
	dp := make([]int, W+1)
	for i := range weights {
		for w := W; w >= weights[i]; w-- { // backward => 0/1
			if cand := dp[w-weights[i]] + values[i]; cand > dp[w] {
				dp[w] = cand
			}
		}
	}
	return dp[W]
}

func editDistance(a, b string) int {
	m, n := len(a), len(b)
	dp := make([]int, n+1)
	for j := 0; j <= n; j++ {
		dp[j] = j
	}
	for i := 1; i <= m; i++ {
		prev := dp[0] // dp[i-1][j-1]
		dp[0] = i
		for j := 1; j <= n; j++ {
			tmp := dp[j]
			if a[i-1] == b[j-1] {
				dp[j] = prev
			} else {
				dp[j] = 1 + min(prev, min(dp[j], dp[j-1]))
			}
			prev = tmp
		}
	}
	return dp[n]
}

