import "sort"

func lengthOfLIS(nums []int) int {
	tails := make([]int, 0, len(nums))
	for _, v := range nums {
		i := sort.SearchInts(tails, v) // first tail >= v
		if i == len(tails) {
			tails = append(tails, v)
		} else {
			tails[i] = v
		}
	}
	return len(tails)
}

func minEatingSpeed(piles []int, h int) int {
	hi := 0
	for _, p := range piles {
		if p > hi {
			hi = p
		}
	}
	feasible := func(speed int) bool {
		hours := 0
		for _, p := range piles {
			hours += (p + speed - 1) / speed // ceil
		}
		return hours <= h
	}
	lo := 1
	for lo < hi {
		mid := lo + (hi-lo)/2
		if feasible(mid) {
			hi = mid
		} else {
			lo = mid + 1
		}
	}
	return lo
}

