func demo(people []Person) {
	// Reflection-based, convenient but slower:
	sort.Slice(people, func(i, j int) bool { return people[i].Age < people[j].Age })

	// Go 1.21+ generic, type-specialized, faster:
	slices.SortFunc(people, func(a, b Person) int { return a.Age - b.Age })

	// Lower-bound search on a sorted []int:
	nums := []int{1, 3, 5, 7, 9}
	i := sort.Search(len(nums), func(i int) bool { return nums[i] >= 5 }) // -> 2
	_ = i

	// Generic binary search (Go 1.21+):
	idx, found := slices.BinarySearch(nums, 7) // idx=3, found=true
	_, _ = idx, found
}

func bellmanFord(n int, edges [][3]int, src int) ([]int, bool) {
	const inf = int(1e18)
	dist := make([]int, n)
	for i := range dist {
		dist[i] = inf
	}
	dist[src] = 0
	for i := 0; i < n-1; i++ {
		changed := false
		for _, e := range edges {
			u, v, w := e[0], e[1], e[2]
			if dist[u] != inf && dist[u]+w < dist[v] {
				dist[v] = dist[u] + w
				changed = true
			}
		}
		if !changed {
			break
		}
	}
	for _, e := range edges { // V-th pass
		u, v, w := e[0], e[1], e[2]
		if dist[u] != inf && dist[u]+w < dist[v] {
			return dist, true // negative cycle
		}
	}
	return dist, false
}

func floydWarshall(dist [][]int) [][]int {
	n := len(dist)
	for k := 0; k < n; k++ {
		for i := 0; i < n; i++ {
			if dist[i][k] == inf {
				continue
			}
			for j := 0; j < n; j++ {
				if dist[k][j] != inf && dist[i][k]+dist[k][j] < dist[i][j] {
					dist[i][j] = dist[i][k] + dist[k][j]
				}
			}
		}
	}
	return dist
}

// inf is a sentinel like int(1e18) chosen so inf+inf does not overflow.

type DSU struct{ parent, rank []int }

func NewDSU(n int) *DSU {
	p := make([]int, n)
	for i := range p {
		p[i] = i
	}
	return &DSU{parent: p, rank: make([]int, n)}
}

func (d *DSU) Find(x int) int {
	for d.parent[x] != x {
		d.parent[x] = d.parent[d.parent[x]] // path halving
		x = d.parent[x]
	}
	return x
}

func (d *DSU) Union(a, b int) bool {
	ra, rb := d.Find(a), d.Find(b)
	if ra == rb {
		return false
	}
	if d.rank[ra] < d.rank[rb] {
		ra, rb = rb, ra
	}
	d.parent[rb] = ra
	if d.rank[ra] == d.rank[rb] {
		d.rank[ra]++
	}
	return true
}

func kruskal(n int, edges [][3]int) (int, [][3]int) {
	sort.Slice(edges, func(i, j int) bool { return edges[i][2] < edges[j][2] })
	dsu := NewDSU(n)
	total := 0
	var mst [][3]int
	for _, e := range edges {
		if dsu.Union(e[0], e[1]) {
			total += e[2]
			mst = append(mst, e)
		}
	}
	return total, mst
}

func tarjanSCC(graph [][]int) [][]int {
	n := len(graph)
	disc := make([]int, n)
	low := make([]int, n)
	onStack := make([]bool, n)
	for i := range disc {
		disc[i] = -1
	}
	var stack []int
	idx := 0
	var sccs [][]int
	var dfs func(u int)
	dfs = func(u int) {
		disc[u], low[u] = idx, idx
		idx++
		stack = append(stack, u)
		onStack[u] = true
		for _, v := range graph[u] {
			if disc[v] == -1 {
				dfs(v)
				low[u] = min(low[u], low[v])
			} else if onStack[v] {
				low[u] = min(low[u], disc[v])
			}
		}
		if low[u] == disc[u] {
			var comp []int
			for {
				w := stack[len(stack)-1]
				stack = stack[:len(stack)-1]
				onStack[w] = false
				comp = append(comp, w)
				if w == u {
					break
				}
			}
			sccs = append(sccs, comp)
		}
	}
	for i := 0; i < n; i++ {
		if disc[i] == -1 {
			dfs(i)
		}
	}
	return sccs
}

func isBipartite(graph [][]int) bool {
	color := make([]int, len(graph)) // 0 = uncolored, 1/-1 colors
	for s := range graph {
		if color[s] != 0 {
			continue
		}
		color[s] = 1
		queue := []int{s}
		for len(queue) > 0 {
			u := queue[0]
			queue = queue[1:]
			for _, v := range graph[u] {
				if color[v] == 0 {
					color[v] = -color[u]
					queue = append(queue, v)
				} else if color[v] == color[u] {
					return false
				}
			}
		}
	}
	return true
}

type item struct {
	node, dist int
}
type pq []item

func (p pq) Len() int            { return len(p) }
func (p pq) Less(i, j int) bool  { return p[i].dist < p[j].dist }
func (p pq) Swap(i, j int)       { p[i], p[j] = p[j], p[i] }
func (p *pq) Push(x any)         { *p = append(*p, x.(item)) }
func (p *pq) Pop() any {
	old := *p
	n := len(old)
	it := old[n-1]
	*p = old[:n-1]
	return it
}

func dijkstra(graph [][][2]int, src int) []int { // graph[u] = list of {v, w}
	dist := make([]int, len(graph))
	for i := range dist {
		dist[i] = math.MaxInt
	}
	dist[src] = 0
	h := &pq{{src, 0}}
	for h.Len() > 0 {
		cur := heap.Pop(h).(item)
		if cur.dist > dist[cur.node] {
			continue // stale
		}
		for _, e := range graph[cur.node] {
			v, w := e[0], e[1]
			if nd := cur.dist + w; nd < dist[v] {
				dist[v] = nd
				heap.Push(h, item{v, nd})
			}
		}
	}
	return dist
}

func knapsack01(weights, values []int, W int) int {
	dp := make([]int, W+1)
	for i := range weights {
		for c := W; c >= weights[i]; c-- { // downward
			if v := dp[c-weights[i]] + values[i]; v > dp[c] {
				dp[c] = v
			}
		}
	}
	return dp[W]
}

func knapsackUnbounded(weights, values []int, W int) int {
	dp := make([]int, W+1)
	for i := range weights {
		for c := weights[i]; c <= W; c++ { // upward
			if v := dp[c-weights[i]] + values[i]; v > dp[c] {
				dp[c] = v
			}
		}
	}
	return dp[W]
}

func matrixChainOrder(p []int) int { // p has n+1 dimensions for n matrices
	n := len(p) - 1
	dp := make([][]int, n)
	for i := range dp {
		dp[i] = make([]int, n)
	}
	for length := 2; length <= n; length++ {
		for i := 0; i+length-1 < n; i++ {
			j := i + length - 1
			dp[i][j] = math.MaxInt
			for k := i; k < j; k++ {
				cost := dp[i][k] + dp[k+1][j] + p[i]*p[k+1]*p[j+1]
				if cost < dp[i][j] {
					dp[i][j] = cost
				}
			}
		}
	}
	return dp[0][n-1]
}

func tsp(dist [][]int) int {
	n := len(dist)
	full := 1<<n - 1
	dp := make([][]int, 1<<n)
	for m := range dp {
		dp[m] = make([]int, n)
		for i := range dp[m] {
			dp[m][i] = math.MaxInt / 2
		}
	}
	dp[1][0] = 0 // start at city 0
	for mask := 1; mask <= full; mask++ {
		for i := 0; i < n; i++ {
			if dp[mask][i] == math.MaxInt/2 || mask&(1<<i) == 0 {
				continue
			}
			for j := 0; j < n; j++ {
				if mask&(1<<j) != 0 {
					continue
				}
				nm := mask | 1<<j
				if c := dp[mask][i] + dist[i][j]; c < dp[nm][j] {
					dp[nm][j] = c
				}
			}
		}
	}
	best := math.MaxInt
	for i := 1; i < n; i++ {
		if c := dp[full][i] + dist[i][0]; c < best {
			best = c
		}
	}
	return best
}

func lengthOfLIS(nums []int) int {
	tails := []int{}
	for _, x := range nums {
		lo, hi := 0, len(tails)
		for lo < hi {
			mid := (lo + hi) / 2
			if tails[mid] < x {
				lo = mid + 1
			} else {
				hi = mid
			}
		}
		if lo == len(tails) {
			tails = append(tails, x)
		} else {
			tails[lo] = x
		}
	}
	return len(tails)
}

func wordBreak(s string, words []string) bool {
	dict := make(map[string]bool, len(words))
	maxLen := 0
	for _, w := range words {
		dict[w] = true
		if len(w) > maxLen {
			maxLen = len(w)
		}
	}
	dp := make([]bool, len(s)+1)
	dp[0] = true
	for i := 1; i <= len(s); i++ {
		for j := i - 1; j >= 0 && i-j <= maxLen; j-- {
			if dp[j] && dict[s[j:i]] {
				dp[i] = true
				break
			}
		}
	}
	return dp[len(s)]
}

func canPartition(nums []int) bool {
	total := 0
	for _, n := range nums {
		total += n
	}
	if total%2 != 0 {
		return false
	}
	target := total / 2
	bits := big.NewInt(1) // bit 0 set: sum 0 reachable
	for _, n := range nums {
		shifted := new(big.Int).Lsh(bits, uint(n))
		bits.Or(bits, shifted)
	}
	return bits.Bit(target) == 1
}

func editDistance(s, t string) int {
	if len(s) < len(t) {
		s, t = t, s
	}
	prev := make([]int, len(t)+1)
	for j := range prev {
		prev[j] = j
	}
	cur := make([]int, len(t)+1)
	for i := 1; i <= len(s); i++ {
		cur[0] = i
		for j := 1; j <= len(t); j++ {
			if s[i-1] == t[j-1] {
				cur[j] = prev[j-1]
			} else {
				cur[j] = 1 + min(prev[j], min(cur[j-1], prev[j-1]))
			}
		}
		prev, cur = cur, prev
	}
	return prev[len(t)]
}

type TreeNode struct {
	Val         int
	Children    []*TreeNode
}

func maxIndependentSet(root *TreeNode) int {
	var dfs func(n *TreeNode) (incl, excl int)
	dfs = func(n *TreeNode) (int, int) {
		if n == nil {
			return 0, 0
		}
		incl, excl := n.Val, 0
		for _, c := range n.Children {
			ci, ce := dfs(c)
			incl += ce          // if we take n, children must be excluded
			excl += max(ci, ce) // else children free to choose
		}
		return incl, excl
	}
	i, e := dfs(root)
	return max(i, e)
}

func merge(intervals [][2]int) [][2]int {
	sort.Slice(intervals, func(i, j int) bool { return intervals[i][0] < intervals[j][0] })
	res := [][2]int{}
	for _, iv := range intervals {
		if n := len(res); n > 0 && iv[0] <= res[n-1][1] {
			if iv[1] > res[n-1][1] {
				res[n-1][1] = iv[1]
			}
		} else {
			res = append(res, iv)
		}
	}
	return res
}

func minMeetingRooms(intervals [][2]int) int {
	n := len(intervals)
	starts := make([]int, n)
	ends := make([]int, n)
	for i, iv := range intervals {
		starts[i], ends[i] = iv[0], iv[1]
	}
	sort.Ints(starts)
	sort.Ints(ends)
	rooms, maxRooms, j := 0, 0, 0
	for i := 0; i < n; i++ {
		for j < n && ends[j] <= starts[i] {
			rooms--
			j++
		}
		rooms++
		if rooms > maxRooms {
			maxRooms = rooms
		}
	}
	return maxRooms
}

func maxNonOverlapping(intervals [][2]int) int {
	sort.Slice(intervals, func(i, j int) bool { return intervals[i][1] < intervals[j][1] })
	count, lastEnd := 0, math.MinInt
	for _, iv := range intervals {
		if iv[0] >= lastEnd {
			count++
			lastEnd = iv[1]
		}
	}
	return count
}

type MedianFinder struct {
	lo *maxHeap // lower half (max-heap)
	hi *minHeap // upper half (min-heap)
}

func (m *MedianFinder) Add(num int) {
	heap.Push(m.lo, num)
	heap.Push(m.hi, heap.Pop(m.lo)) // largest of lo -> hi (keeps order)
	if m.hi.Len() > m.lo.Len() {
		heap.Push(m.lo, heap.Pop(m.hi)) // rebalance
	}
}

func (m *MedianFinder) Median() float64 {
	if m.lo.Len() > m.hi.Len() {
		return float64(m.lo.Peek())
	}
	return (float64(m.lo.Peek()) + float64(m.hi.Peek())) / 2
}

func maxSlidingWindow(nums []int, k int) []int {
	dq := []int{} // indices, values decreasing
	res := make([]int, 0, len(nums)-k+1)
	for i, x := range nums {
		for len(dq) > 0 && nums[dq[len(dq)-1]] <= x {
			dq = dq[:len(dq)-1]
		}
		dq = append(dq, i)
		if dq[0] <= i-k {
			dq = dq[1:]
		}
		if i >= k-1 {
			res = append(res, nums[dq[0]])
		}
	}
	return res
}

func quickSelect(nums []int, k int) int { // kth largest (1-indexed)
	target := len(nums) - k // index in sorted ascending order
	lo, hi := 0, len(nums)-1
	for lo < hi {
		p := partition(nums, lo, hi)
		switch {
		case p == target:
			return nums[p]
		case p < target:
			lo = p + 1
		default:
			hi = p - 1
		}
	}
	return nums[lo]
}

func partition(a []int, lo, hi int) int {
	rand.Seed(time.Now().UnixNano())
	pi := lo + rand.Intn(hi-lo+1)
	a[pi], a[hi] = a[hi], a[pi] // random pivot to hi
	pivot := a[hi]
	i := lo
	for j := lo; j < hi; j++ {
		if a[j] < pivot {
			a[i], a[j] = a[j], a[i]
			i++
		}
	}
	a[i], a[hi] = a[hi], a[i]
	return i
}

type Trie struct {
	children [26]*Trie
	isWord   bool
}

func (t *Trie) Insert(word string) {
	node := t
	for i := 0; i < len(word); i++ {
		c := word[i] - 'a'
		if node.children[c] == nil {
			node.children[c] = &Trie{}
		}
		node = node.children[c]
	}
	node.isWord = true
}

func (t *Trie) find(s string) *Trie {
	node := t
	for i := 0; i < len(s); i++ {
		node = node.children[s[i]-'a']
		if node == nil {
			return nil
		}
	}
	return node
}

func (t *Trie) Search(word string) bool { n := t.find(word); return n != nil && n.isWord }
func (t *Trie) StartsWith(p string) bool { return t.find(p) != nil }

func findWords(board [][]byte, words []string) []string {
	root := &Trie{}
	for _, w := range words {
		root.Insert(w)
	}
	var res []string
	var dfs func(r, c int, node *Trie, path []byte)
	dfs = func(r, c int, node *Trie, path []byte) {
		if r < 0 || c < 0 || r >= len(board) || c >= len(board[0]) || board[r][c] == '#' {
			return
		}
		ch := board[r][c]
		nxt := node.children[ch-'a']
		if nxt == nil {
			return
		}
		path = append(path, ch)
		if nxt.isWord {
			res = append(res, string(path))
			nxt.isWord = false // dedupe
		}
		board[r][c] = '#'
		dfs(r+1, c, nxt, path)
		dfs(r-1, c, nxt, path)
		dfs(r, c+1, nxt, path)
		dfs(r, c-1, nxt, path)
		board[r][c] = ch
	}
	for r := range board {
		for c := range board[r] {
			dfs(r, c, root, nil)
		}
	}
	return res
}

func kmpSearch(text, pat string) []int {
	if len(pat) == 0 {
		return []int{0}
	}
	pi := make([]int, len(pat))
	for i, k := 1, 0; i < len(pat); i++ {
		for k > 0 && pat[i] != pat[k] {
			k = pi[k-1]
		}
		if pat[i] == pat[k] {
			k++
		}
		pi[i] = k
	}
	var res []int
	for i, k := 0, 0; i < len(text); i++ {
		for k > 0 && text[i] != pat[k] {
			k = pi[k-1]
		}
		if text[i] == pat[k] {
			k++
		}
		if k == len(pat) {
			res = append(res, i-k+1)
			k = pi[k-1]
		}
	}
	return res
}

func rabinKarp(text, pat string) []int {
	n, m := len(text), len(pat)
	if m == 0 || m > n {
		return nil
	}
	const base, mod = 256, 1_000_000_007
	var patHash, winHash, pow int64 = 0, 0, 1
	for i := 0; i < m; i++ {
		patHash = (patHash*base + int64(pat[i])) % mod
		winHash = (winHash*base + int64(text[i])) % mod
		if i > 0 {
			pow = pow * base % mod
		}
	}
	var res []int
	for i := 0; i+m <= n; i++ {
		if patHash == winHash && text[i:i+m] == pat {
			res = append(res, i)
		}
		if i+m < n {
			winHash = (winHash - int64(text[i])*pow%mod + mod) % mod
			winHash = (winHash*base + int64(text[i+m])) % mod
		}
	}
	return res
}

func buildPrefix2D(m [][]int) [][]int {
	R, C := len(m), len(m[0])
	P := make([][]int, R+1)
	for i := range P {
		P[i] = make([]int, C+1)
	}
	for i := 1; i <= R; i++ {
		for j := 1; j <= C; j++ {
			P[i][j] = m[i-1][j-1] + P[i-1][j] + P[i][j-1] - P[i-1][j-1]
		}
	}
	return P
}

func submatrixSum(P [][]int, r1, c1, r2, c2 int) int { // inclusive
	return P[r2+1][c2+1] - P[r1][c2+1] - P[r2+1][c1] + P[r1][c1]
}

type SegTree struct {
	n    int
	tree []int
}

func NewSegTree(a []int) *SegTree {
	n := len(a)
	st := &SegTree{n: n, tree: make([]int, 2*n)}
	copy(st.tree[n:], a) // leaves
	for i := n - 1; i > 0; i-- {
		st.tree[i] = st.tree[2*i] + st.tree[2*i+1]
	}
	return st
}

func (st *SegTree) Update(i, val int) { // point assign
	i += st.n
	st.tree[i] = val
	for i >>= 1; i > 0; i >>= 1 {
		st.tree[i] = st.tree[2*i] + st.tree[2*i+1]
	}
}

func (st *SegTree) Query(l, r int) int { // sum over [l, r)
	res := 0
	for l, r = l+st.n, r+st.n; l < r; l, r = l>>1, r>>1 {
		if l&1 == 1 {
			res += st.tree[l]
			l++
		}
		if r&1 == 1 {
			r--
			res += st.tree[r]
		}
	}
	return res
}

func jump(nums []int) int { // minimum jumps to reach last index
	jumps, curEnd, farthest := 0, 0, 0
	for i := 0; i < len(nums)-1; i++ {
		if i+nums[i] > farthest {
			farthest = i + nums[i]
		}
		if i == curEnd { // must jump now
			jumps++
			curEnd = farthest
		}
	}
	return jumps
}

func canCompleteCircuit(gas, cost []int) int {
	total, tank, start := 0, 0, 0
	for i := range gas {
		d := gas[i] - cost[i]
		total += d
		tank += d
		if tank < 0 {
			start = i + 1
			tank = 0
		}
	}
	if total < 0 {
		return -1
	}
	return start
}

func leastInterval(tasks []byte, n int) int {
	var count [26]int
	for _, t := range tasks {
		count[t-'A']++
	}
	maxFreq, numMax := 0, 0
	for _, c := range count {
		if c > maxFreq {
			maxFreq, numMax = c, 1
		} else if c == maxFreq {
			numMax++
		}
	}
	frames := (maxFreq-1)*(n+1) + numMax
	if frames < len(tasks) {
		return len(tasks)
	}
	return frames
}

func gcd(a, b int) int {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

func lcm(a, b int) int { return a / gcd(a, b) * b }

func powMod(base, exp, mod int64) int64 {
	result := int64(1)
	base %= mod
	for exp > 0 {
		if exp&1 == 1 {
			result = result * base % mod
		}
		base = base * base % mod
		exp >>= 1
	}
	return result
}

func sieve(n int) []int {
	if n < 2 {
		return nil
	}
	isComposite := make([]bool, n+1)
	var primes []int
	for p := 2; p <= n; p++ {
		if !isComposite[p] {
			primes = append(primes, p)
			for m := p * p; m <= n; m += p {
				isComposite[m] = true
			}
		}
	}
	return primes
}

func countBits(n uint) int {
	c := 0
	for n != 0 {
		n &= n - 1
		c++
	}
	return c
}

func singleNumber(nums []int) int {
	x := 0
	for _, v := range nums {
		x ^= v
	}
	return x
}

func subsets(mask int) []int {
	var res []int
	for sub := mask; ; sub = (sub - 1) & mask {
		res = append(res, sub)
		if sub == 0 {
			break
		}
	}
	return res
}

type lfuNode struct {
	key, val, freq int
	prev, next     *lfuNode
}

type LFUCache struct {
	cap, size, minFreq int
	nodes              map[int]*lfuNode
	freqList           map[int]*dll // freq -> doubly linked list (head=MRU)
}

func (c *LFUCache) Get(key int) (int, bool) {
	n, ok := c.nodes[key]
	if !ok {
		return 0, false
	}
	c.bump(n)
	return n.val, true
}

func (c *LFUCache) bump(n *lfuNode) {
	c.freqList[n.freq].remove(n)
	if n.freq == c.minFreq && c.freqList[n.freq].empty() {
		c.minFreq++
	}
	n.freq++
	if c.freqList[n.freq] == nil {
		c.freqList[n.freq] = newDLL()
	}
	c.freqList[n.freq].pushFront(n)
}

func (c *LFUCache) Put(key, val int) {
	if c.cap == 0 {
		return
	}
	if n, ok := c.nodes[key]; ok {
		n.val = val
		c.bump(n)
		return
	}
	if c.size == c.cap {
		victim := c.freqList[c.minFreq].popBack()
		delete(c.nodes, victim.key)
		c.size--
	}
	n := &lfuNode{key: key, val: val, freq: 1}
	c.nodes[key] = n
	if c.freqList[1] == nil {
		c.freqList[1] = newDLL()
	}
	c.freqList[1].pushFront(n)
	c.minFreq = 1
	c.size++
}

type MinStack struct {
	stack []int
	mins  []int // running minimum, parallel to stack
}

func (s *MinStack) Push(x int) {
	s.stack = append(s.stack, x)
	if len(s.mins) == 0 || x < s.mins[len(s.mins)-1] {
		s.mins = append(s.mins, x)
	} else {
		s.mins = append(s.mins, s.mins[len(s.mins)-1])
	}
}

func (s *MinStack) Pop() {
	s.stack = s.stack[:len(s.stack)-1]
	s.mins = s.mins[:len(s.mins)-1]
}

func (s *MinStack) Top() int    { return s.stack[len(s.stack)-1] }
func (s *MinStack) GetMin() int { return s.mins[len(s.mins)-1] }

type RandomizedSet struct {
	vals []int
	idx  map[int]int // value -> position in vals
}

func NewRandomizedSet() *RandomizedSet {
	return &RandomizedSet{idx: make(map[int]int)}
}

func (s *RandomizedSet) Insert(v int) bool {
	if _, ok := s.idx[v]; ok {
		return false
	}
	s.idx[v] = len(s.vals)
	s.vals = append(s.vals, v)
	return true
}

func (s *RandomizedSet) Remove(v int) bool {
	i, ok := s.idx[v]
	if !ok {
		return false
	}
	last := len(s.vals) - 1
	s.vals[i] = s.vals[last]
	s.idx[s.vals[i]] = i
	s.vals = s.vals[:last]
	delete(s.idx, v)
	return true
}

func (s *RandomizedSet) GetRandom() int { return s.vals[rand.Intn(len(s.vals))] }

type TokenBucket struct {
	mu         sync.Mutex
	capacity   float64
	tokens     float64
	rate       float64 // tokens per second
	lastRefill time.Time
}

func NewTokenBucket(capacity, rate float64) *TokenBucket {
	return &TokenBucket{capacity: capacity, tokens: capacity, rate: rate, lastRefill: time.Now()}
}

func (b *TokenBucket) Allow() bool {
	b.mu.Lock()
	defer b.mu.Unlock()
	now := time.Now()
	elapsed := now.Sub(b.lastRefill).Seconds()
	b.tokens = math.Min(b.capacity, b.tokens+elapsed*b.rate)
	b.lastRefill = now
	if b.tokens >= 1 {
		b.tokens--
		return true
	}
	return false
}

// Channel-based (idiomatic).
type BlockingQueue[T any] struct{ ch chan T }

func NewBlockingQueue[T any](capacity int) *BlockingQueue[T] {
	return &BlockingQueue[T]{ch: make(chan T, capacity)}
}

func (q *BlockingQueue[T]) Put(v T)        { q.ch <- v }          // blocks if full
func (q *BlockingQueue[T]) Take() T         { return <-q.ch }      // blocks if empty
func (q *BlockingQueue[T]) Close()          { close(q.ch) }

// With cancellation:
func (q *BlockingQueue[T]) PutCtx(ctx context.Context, v T) error {
	select {
	case q.ch <- v:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

func parallelMergeSort(a []int, depth int) {
	if len(a) <= 2048 || depth <= 0 {
		sort.Ints(a) // sequential fallback
		return
	}
	mid := len(a) / 2
	var wg sync.WaitGroup
	wg.Add(1)
	go func() {
		defer wg.Done()
		parallelMergeSort(a[:mid], depth-1)
	}()
	parallelMergeSort(a[mid:], depth-1) // run other half inline
	wg.Wait()
	merge(a, mid)
}

func merge(a []int, mid int) {
	left := append([]int(nil), a[:mid]...)
	right := a[mid:]
	i, j, k := 0, 0, 0
	for i < len(left) && j < len(right) {
		if left[i] <= right[j] {
			a[k] = left[i]
			i++
		} else {
			a[k] = right[j]
			j++
		}
		k++
	}
	for i < len(left) {
		a[k] = left[i]
		i, k = i+1, k+1
	}
}

type LRUCache struct {
	mu       sync.Mutex
	capacity int
	cache    map[int]*list.Element
	ll       *list.List // front = most recently used
}

type entry struct{ key, value int }

func (c *LRUCache) Get(key int) (int, bool) {
	c.mu.Lock()
	defer c.mu.Unlock()
	if el, ok := c.cache[key]; ok {
		c.ll.MoveToFront(el) // mutation => write lock required
		return el.Value.(*entry).value, true
	}
	return 0, false
}

func (c *LRUCache) Put(key, value int) {
	c.mu.Lock()
	defer c.mu.Unlock()
	if el, ok := c.cache[key]; ok {
		el.Value.(*entry).value = value
		c.ll.MoveToFront(el)
		return
	}
	if c.ll.Len() == c.capacity {
		oldest := c.ll.Back()
		c.ll.Remove(oldest)
		delete(c.cache, oldest.Value.(*entry).key)
	}
	c.cache[key] = c.ll.PushFront(&entry{key, value})
}

func reservoirSample(stream <-chan int, k int) []int {
	res := make([]int, 0, k)
	i := 0
	for v := range stream {
		i++
		if len(res) < k {
			res = append(res, v)
		} else if j := rand.Intn(i); j < k {
			res[j] = v // replace a uniformly random slot
		}
	}
	return res
}

func majorityElement(nums []int) int {
	candidate, count := 0, 0
	for _, v := range nums {
		if count == 0 {
			candidate = v
		}
		if v == candidate {
			count++
		} else {
			count--
		}
	}
	// Verify if a majority is not guaranteed to exist:
	count = 0
	for _, v := range nums {
		if v == candidate {
			count++
		}
	}
	if count > len(nums)/2 {
		return candidate
	}
	return -1 // no majority
}
